import React, { useEffect, useState } from 'react'
import {Link} from "react-router-dom";
import './Reports.css'
import axios from "axios";




export default function Reports() {

    const localUser = JSON.parse(localStorage.getItem('user'));
    const [userRole, setUserRole] = useState(null);
    const [admin, setAdmin] = useState([]);
    const [accessData, setAccessData] = useState([]);



    useEffect(() => {
        const getUser = async () => {
            try {
                const user = await axios.get('/api/user/' + localUser._id);
                const roleId = user.data.role_id;
                setUserRole(roleId);
                setAdmin(user.data.isadmin)
                const resPermission = await axios.get('/api/permission/' + roleId);
                const permissions = resPermission.data[0]?.get_permissions; // Используем опциональную цепочку

                if (permissions.length > 0) {
                    setAccessData(permissions);
                } else {
                    setAccessData([]); // Устанавливаем пустой массив, если разрешения не найдены
                }

                setUser(user.data);
            } catch (error) {
                console.error('Error fetching data:', error);
                // Здесь можно добавить обработку ошибки, например, показать пользователю сообщение об ошибке
            }
        }

        getUser();
    }, [localUser._id]);


    const hasAccess = (toolId) => {
        return accessData.some(item => item.tool_id === toolId && item.is_accessible);
    };

    return (
        <div className="ReportsButton">
            {userRole !== null && (
                <>
                    {admin ? (
                        <>
                            <Link to='/ReportsHistory' className='linkReports'>Отчет по истории</Link>
                            <br />
                            <Link to='/ReportsNominations' className='linkReports'>Отчет по номинациям</Link>
                        </>
                    ) : (
                        <>
                            {hasAccess(10) && (
                                <>
                                    <Link to='/ReportsHistory' className='linkReports'>Отчет по истории</Link>
                                    <br />
                                </>
                            )}
                            {hasAccess(11) && (
                                <Link to='/ReportsNominations' className='linkReports'>Отчет по номинациям</Link>
                            )}
                        </>
                    )}
                </>
            )}
        </div>
    );
};
